<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Field={key:string;label:string;kind:'text'|'textarea'|'number'|'date'|'select';required:boolean;options:string[]}; type Template={id:string;title:string;category:string;description:string;fields:Field[];submission_count?:number;is_active:boolean}; type Submission={id:string;title:string;employee?:string;status:string;payload:Record<string,string>;created_at:string};
 let templates=$state<Template[]>([]),submissions=$state<Submission[]>([]),title=$state(''),category=$state('general'),description=$state(''),fieldLines=$state('Lokasi|text|required\nJenis|select|required|Audit,Instalasi'),reviewNote=$state(''),reviewing=$state(''),error=$state(''),loading=$state(true),saving=$state(false);
 function fields():Field[]{return fieldLines.split(/\r?\n/).map((line,index)=>{const [label='',kind='text',required='',options='']=line.split('|').map(x=>x.trim());return {key:label.toLowerCase().replace(/[^a-z0-9]+/g,'_')||`field_${index+1}`,label,kind:kind as Field['kind'],required:required==='required',options:options.split(',').filter(Boolean)};}).filter(x=>x.label);}
 async function load(){loading=true;try{const data=await request<{templates:Template[];submissions:Submission[]}>('/v1/admin/custom-forms');templates=data.templates;submissions=data.submissions;}catch(cause){error=cause instanceof Error?cause.message:'Tidak dapat memuat formulir.';}finally{loading=false;}}
 async function create(){saving=true;try{await request('/v1/admin/custom-forms',{method:'POST',body:JSON.stringify({title,category,description,fields:fields()})});title='';description='';await load();}finally{saving=false;}}
 async function review(id:string){saving=true;try{await request(`/v1/admin/custom-forms/submissions/${id}/review`,{method:'POST',body:JSON.stringify({note:reviewNote})});reviewing='';reviewNote='';await load();}finally{saving=false;}}
 async function templateState(id:string,is_active:boolean){saving=true;try{await request(`/v1/admin/custom-forms/${id}/state`,{method:'POST',body:JSON.stringify({is_active})});await load();}finally{saving=false;}}
 onMount(load);
</script>
<main class="workspace-page"><PageHeader title="Custom forms" description="Template, respons, dan review dalam satu workflow." backHref="/admin/dashboard"/>
{#if error}<p class="alert">{error}</p>{/if}
<div class="layout"><section class="panel"><h2>Template baru</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void create();}}><input bind:value={title} placeholder="Nama" required/><input bind:value={category} placeholder="Kategori" required/><textarea bind:value={description} placeholder="Deskripsi"></textarea><textarea bind:value={fieldLines} rows="5" required></textarea><button disabled={saving}>Buat template</button></form></section><section class="panel"><header><h2>Template</h2><RefreshButton onclick={load} label="Muat ulang"/></header>{#each templates as template (template.id)}<article><strong>{template.title}</strong><small>{template.category} · {template.fields.length} field · {template.submission_count ?? 0} respons · {template.is_active?'aktif':'nonaktif'}</small><button class="quiet" disabled={saving} onclick={()=>templateState(template.id,!template.is_active)}>{template.is_active?'Nonaktifkan':'Aktifkan'}</button></article>{:else}<p class="muted">Belum ada template.</p>{/each}</section></div>
<section class="panel"><h2>Submission terbaru</h2>{#each submissions as submission (submission.id)}<article><strong>{submission.title}</strong><small>{submission.employee ?? 'Karyawan'} · {submission.status}</small><p>{Object.entries(submission.payload).map(([key,value])=>`${key}: ${value}`).join(' · ')}</p>{#if submission.status==='submitted'}<button class="quiet" disabled={saving} onclick={()=>reviewing=submission.id}>Review</button>{#if reviewing===submission.id}<form novalidate onsubmit={(e)=>{e.preventDefault();void review(submission.id);}}><input bind:value={reviewNote} placeholder="Catatan review"/><button disabled={saving}>Simpan</button></form>{/if}{/if}</article>{:else}<p class="muted">Belum ada submission.</p>{/each}</section></main>
<style>.workspace-page,.layout{display:grid;gap:12px}.layout{grid-template-columns:1fr 1fr}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:8px}article{border-top:1px solid var(--line);padding:10px 0}small,p{display:block;color:var(--muted);font-size:12px}.quiet{margin-top:8px;background:var(--surface-alt);border:1px solid var(--line);color:var(--text)}.alert{color:var(--danger)}@media(max-width:720px){.layout{grid-template-columns:1fr}}</style>
